insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Proton nuclear magnetic resonance: Chemical shifts', 'Chemical shift values, symbolized by δ, are not precise, but typical – they are to be therefore regarded mainly as a reference. Deviations are in ±0.2 ppm range, sometimes more. The exact value of chemical shift depends on molecular structure and the solvent, temperature, magnetic field in which the spectrum is being recorded and other neighboring functional groups. Hydrogen nuclei are sensitive to the hybridization of the atom to which the hydrogen atom is attached and to electronic effects. Nuclei tend to be deshielded by groups that withdraw electron density. Deshielded nuclei resonate at higher δ values, whereas shielded nuclei resonate at lower δ values. Examples of electron withdrawing substituents are −OH, −OCOR, −OR, −NO2 and halogens. These cause a downfield shift of approximately 2–4 ppm for H atoms on Cα (an aliphatic C atom directly bonded to the substituent in question) and of less than 1–2 ppm for H atoms on Cβ (an aliphatic C atom bonded to Cα). Carbonyl groups, olefinic fragments and aromatic rings contribute sp2 hybridized carbon atoms to an aliphatic chain. This causes a downfield shift of 1–2 ppm at Cα.', 'Wikipedia: Proton nuclear magnetic resonance', 'https://en.wikipedia.org/w/index.php?title=Proton_nuclear_magnetic_resonance&oldid=1380132839', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Chemical shift values, symbolized by δ, are not precise, but typical – they are to be therefore regarded mainly as a reference. Deviations are in ±0.2 ppm range, sometimes more. The exact value of chemical shift depends on molecular structure and the solvent, temperature, magnetic field in which the spectrum is being recorded and other neighboring functional groups. Hydrogen nuclei are sensitive to the hybridization of the atom to which the hydrogen atom is attached and to electronic effects. Nuclei tend to be deshielded by groups that withdraw electron density. Deshielded nuclei resonate at higher δ values, whereas shielded nuclei resonate at lower δ values. Examples of electron withdrawing substituents are −OH, −OCOR, −OR, −NO2 and halogens. These cause a downfield shift of approximately 2–4 ppm for H atoms on Cα (an aliphatic C atom directly bonded to the substituent in question) and of less than 1–2 ppm for H atoms on Cβ (an aliphatic C atom bonded to Cα). Carbonyl groups, olefinic fragments and aromatic rings contribute sp2 hybridized carbon atoms to an aliphatic chain. This causes a downfield shift of 1–2 ppm at Cα.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Proton nuclear magnetic resonance: Chemical shifts', 'Note that labile protons (−OH, −NH2, −SH) have no characteristic chemical shift. However, such resonances can be identified by the disappearance of a peak when reacted with D2O, as deuterium will replace a protium atom. This method is called a D2O shake. Acidic protons may also be suppressed when a solvent containing acidic deuterium ions (e.g. methanol-d4) is used. An alternate method for identifying protons that are not attached to carbons is the heteronuclear single quantum coherence (HSQC) experiment, which correlates protons and carbons that are one bond away from each other. A hydrogen that is not attached to a carbon can be identified because it does not have a crosspeak in the HSQC spectrum.', 'Wikipedia: Proton nuclear magnetic resonance', 'https://en.wikipedia.org/w/index.php?title=Proton_nuclear_magnetic_resonance&oldid=1380132839', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Note that labile protons (−OH, −NH2, −SH) have no characteristic chemical shift. However, such resonances can be identified by the disappearance of a peak when reacted with D2O, as deuterium will replace a protium atom. This method is called a D2O shake. Acidic protons may also be suppressed when a solvent containing acidic deuterium ions (e.g. methanol-d4) is used. An alternate method for identifying protons that are not attached to carbons is the heteronuclear single quantum coherence (HSQC) experiment, which correlates protons and carbons that are one bond away from each other. A hydrogen that is not attached to a carbon can be identified because it does not have a crosspeak in the HSQC spectrum.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Proton nuclear magnetic resonance: Signal intensity', 'The integrated intensities of NMR signals are, ideally, proportional to the ratio of the nuclei within the molecule. Together with chemical shift and coupling constants, the integrated intensities allow structural assignments. For mixtures, the signal intensities can be used to determine molar ratios. These considerations are valid only when sufficient time is allowed for full relaxation of the affected signals, as determined by their T1 values. A further complication arises from the difficulty of integrating signals of very different line shapes.', 'Wikipedia: Proton nuclear magnetic resonance', 'https://en.wikipedia.org/w/index.php?title=Proton_nuclear_magnetic_resonance&oldid=1380132839', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The integrated intensities of NMR signals are, ideally, proportional to the ratio of the nuclei within the molecule. Together with chemical shift and coupling constants, the integrated intensities allow structural assignments. For mixtures, the signal intensities can be used to determine molar ratios. These considerations are valid only when sufficient time is allowed for full relaxation of the affected signals, as determined by their T1 values. A further complication arises from the difficulty of integrating signals of very different line shapes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Proton nuclear magnetic resonance: Spin–spin couplings', 'In addition to chemical shift, NMR spectra allow structural assignments by virtue of spin–spin coupling (and integrated intensities). Because nuclei themselves possess a small magnetic field, they influence each other, changing the energy and hence frequency of nearby nuclei as they resonate—this is known as spin–spin coupling. The most important type in basic NMR is scalar coupling. This interaction between two nuclei occurs through chemical bonds, and can typically be seen up to three bonds away (3-J coupling), although it can occasionally be visible over four to five bonds, though these tend to be considerably weaker. The effect of scalar coupling can be understood by examination of a proton which has a signal at 1 ppm. This proton is in a hypothetical molecule where three bonds away exists another proton (in a CH−CH group, for instance), the neighbouring group (a magnetic field) causes the signal at 1 ppm to split into two, with one peak being a few hertz higher than 1 ppm and the other peak being the same amount lower than 1 ppm. These peaks each have half the area of the former singlet peak. The magnitude of this splitting (difference in frequency between peaks) is known as the coupling constant. A typical coupling constant value for aliphatic protons would be 7 Hz.', 'Wikipedia: Proton nuclear magnetic resonance', 'https://en.wikipedia.org/w/index.php?title=Proton_nuclear_magnetic_resonance&oldid=1380132839', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'In addition to chemical shift, NMR spectra allow structural assignments by virtue of spin–spin coupling (and integrated intensities). Because nuclei themselves possess a small magnetic field, they influence each other, changing the energy and hence frequency of nearby nuclei as they resonate—this is known as spin–spin coupling. The most important type in basic NMR is scalar coupling. This interaction between two nuclei occurs through chemical bonds, and can typically be seen up to three bonds away (3-J coupling), although it can occasionally be visible over four to five bonds, though these tend to be considerably weaker. The effect of scalar coupling can be understood by examination of a proton which has a signal at 1 ppm. This proton is in a hypothetical molecule where three bonds away exists another proton (in a CH−CH group, for instance), the neighbouring group (a magnetic field) causes the signal at 1 ppm to split into two, with one peak being a few hertz higher than 1 ppm and the other peak being the same amount lower than 1 ppm. These peaks each have half the area of the former singlet peak. The magnitude of this splitting (difference in frequency between peaks) is known as the coupling constant. A typical coupling constant value for aliphatic protons would be 7 Hz.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Proton nuclear magnetic resonance: Spin–spin couplings', 'The coupling constant is independent of magnetic field strength because it is caused by the magnetic field of another nucleus, not the spectrometer magnet. Therefore, it is quoted in hertz (frequency) and not ppm (chemical shift). If a proton resonates at 2.5 ppm and another at 1 ppm, the proton at 2.5 ppm would be split into two by the proton at 1 ppm. Because the magnitude of interaction is the same, the splitting would have the same coupling constant 7 Hz apart. The spectrum would have two signals, each being a doublet. Each doublet will have the same area because both doublets are produced by one proton each. If the two doublets at 1 ppm and 2.5 ppm from the fictional molecule CH−CH were changed into CH2−CH, the total area of the 1 ppm CH2 peak will be twice that of the 2.5 ppm CH peak.The CH2 peak would also be split into a doublet by the CH peak—with one peak at 1 ppm + 3.5 Hz and one at 1 ppm − 3.5 Hz (total splitting or coupling constant is 7 Hz).', 'Wikipedia: Proton nuclear magnetic resonance', 'https://en.wikipedia.org/w/index.php?title=Proton_nuclear_magnetic_resonance&oldid=1380132839', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The coupling constant is independent of magnetic field strength because it is caused by the magnetic field of another nucleus, not the spectrometer magnet. Therefore, it is quoted in hertz (frequency) and not ppm (chemical shift). If a proton resonates at 2.5 ppm and another at 1 ppm, the proton at 2.5 ppm would be split into two by the proton at 1 ppm. Because the magnitude of interaction is the same, the splitting would have the same coupling constant 7 Hz apart. The spectrum would have two signals, each being a doublet. Each doublet will have the same area because both doublets are produced by one proton each. If the two doublets at 1 ppm and 2.5 ppm from the fictional molecule CH−CH were changed into CH2−CH, the total area of the 1 ppm CH2 peak will be twice that of the 2.5 ppm CH peak.The CH2 peak would also be split into a doublet by the CH peak—with one peak at 1 ppm + 3.5 Hz and one at 1 ppm − 3.5 Hz (total splitting or coupling constant is 7 Hz).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry', 'Mass spectrometry (MS) is an analytical technique that is used to measure the mass-to-charge ratio of ions. The results are presented as a mass spectrum, a plot of intensity as a function of the mass-to-charge ratio. These spectra are used to determine the elemental or isotopic signature of a sample, the masses of particles and of molecules, and to elucidate the chemical identity or structure of molecules and other chemical compounds. Mass spectrometry is used in many different fields and is applied to pure samples as well as complex mixtures.', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Mass spectrometry (MS) is an analytical technique that is used to measure the mass-to-charge ratio of ions. The results are presented as a mass spectrum, a plot of intensity as a function of the mass-to-charge ratio. These spectra are used to determine the elemental or isotopic signature of a sample, the masses of particles and of molecules, and to elucidate the chemical identity or structure of molecules and other chemical compounds. Mass spectrometry is used in many different fields and is applied to pure samples as well as complex mixtures.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry', 'In a typical MS procedure, a sample, which may be solid, liquid, or gaseous, is ionized, for example by bombarding it with a beam of electrons. This may cause some of the sample''s molecules to break up into positively charged fragments or simply become positively charged without fragmenting. These ions (fragments) are then separated according to their mass-to-charge ratio, for example by accelerating them and subjecting them to an electric or magnetic field: ions of the same mass-to-charge ratio will undergo the same amount of deflection. The ions are detected by a mechanism capable of detecting charged particles, such as an electron multiplier. Results are displayed as spectra of the signal intensity of detected ions as a function of the mass-to-charge ratio. The atoms or molecules in the sample can be identified by correlating known masses (e.g. an entire molecule) to the identified masses or through a characteristic fragmentation pattern.', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'In a typical MS procedure, a sample, which may be solid, liquid, or gaseous, is ionized, for example by bombarding it with a beam of electrons. This may cause some of the sample''s molecules to break up into positively charged fragments or simply become positively charged without fragmenting. These ions (fragments) are then separated according to their mass-to-charge ratio, for example by accelerating them and subjecting them to an electric or magnetic field: ions of the same mass-to-charge ratio will undergo the same amount of deflection. The ions are detected by a mechanism capable of detecting charged particles, such as an electron multiplier. Results are displayed as spectra of the signal intensity of detected ions as a function of the mass-to-charge ratio. The atoms or molecules in the sample can be identified by correlating known masses (e.g. an entire molecule) to the identified masses or through a characteristic fragmentation pattern.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Components', 'A mass spectrometer consists of 5 components: sample inlet, ion source (or ionizer), mass analyzer, detector, data system. Each component can be varied somewhat independently from the other components, and the full mass spectrometer itself can be included as a component in an analysis pipeline, allowing great flexibility. The sample inlet prepares the sample to be analyzed in a suitable state. The ion source takes samples from the sample inlet, converts a portion of the sample into a stream of ions, and outputs it to the mass analyzer. There is a wide variety of ionization techniques, depending on the phase (solid, liquid, gas) of the sample and the efficiency of various ionization mechanisms for the unknown species. An extraction system removes ions from the sample, which are then targeted into the mass analyzer. The mass analyzer takes an input stream of ions and separates ("analyzes") its constituent ions according to their m/z, the mass-to-charge ratio. The detector measures the value of an indicator quantity and thus provides data for calculating the abundances of each ion present. Some detectors also give spatial information, e.g., a multichannel plate.', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'A mass spectrometer consists of 5 components: sample inlet, ion source (or ionizer), mass analyzer, detector, data system. Each component can be varied somewhat independently from the other components, and the full mass spectrometer itself can be included as a component in an analysis pipeline, allowing great flexibility. The sample inlet prepares the sample to be analyzed in a suitable state. The ion source takes samples from the sample inlet, converts a portion of the sample into a stream of ions, and outputs it to the mass analyzer. There is a wide variety of ionization techniques, depending on the phase (solid, liquid, gas) of the sample and the efficiency of various ionization mechanisms for the unknown species. An extraction system removes ions from the sample, which are then targeted into the mass analyzer. The mass analyzer takes an input stream of ions and separates ("analyzes") its constituent ions according to their m/z, the mass-to-charge ratio. The detector measures the value of an indicator quantity and thus provides data for calculating the abundances of each ion present. Some detectors also give spatial information, e.g., a multichannel plate.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Illustrative example', 'The following describes the operation of a simple mass spectrometer that uses sector type. Other types are treated below. Consider a sample of sodium chloride (table salt). In the ion source, the sample is vaporized (turned into gas) and ionized (transformed into electrically charged particles) into sodium (Na+) and chloride (Cl−) ions. Sodium atoms and ions are monoisotopic, with a mass of about 23 daltons (symbol: Da or older symbol: u). Chloride atoms and ions come in two stable isotopes with masses of approximately 35 u (at a natural abundance of about 75 percent) and approximately 37 u (at a natural abundance of about 25 percent). The analyzer part of the spectrometer contains electric and magnetic fields, which exert forces on ions traveling through these fields. The speed of a charged particle may be increased or decreased while passing through the electric field, and its direction may be altered by the magnetic field. The magnitude of the deflection of the moving ion''s trajectory depends on its mass-to-charge ratio. Lighter ions are deflected by the magnetic force to a greater degree than heavier ions (based on Newton''s second law of motion, F = ma).', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The following describes the operation of a simple mass spectrometer that uses sector type. Other types are treated below. Consider a sample of sodium chloride (table salt). In the ion source, the sample is vaporized (turned into gas) and ionized (transformed into electrically charged particles) into sodium (Na+) and chloride (Cl−) ions. Sodium atoms and ions are monoisotopic, with a mass of about 23 daltons (symbol: Da or older symbol: u). Chloride atoms and ions come in two stable isotopes with masses of approximately 35 u (at a natural abundance of about 75 percent) and approximately 37 u (at a natural abundance of about 25 percent). The analyzer part of the spectrometer contains electric and magnetic fields, which exert forces on ions traveling through these fields. The speed of a charged particle may be increased or decreased while passing through the electric field, and its direction may be altered by the magnetic field. The magnitude of the deflection of the moving ion''s trajectory depends on its mass-to-charge ratio. Lighter ions are deflected by the magnetic force to a greater degree than heavier ions (based on Newton''s second law of motion, F = ma).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Illustrative example', 'The streams of magnetically sorted ions pass from the analyzer to the detector, which records the relative abundance of each ion type. This information is used to determine the chemical element composition of the original sample (i.e. that both sodium and chlorine are present in the sample) and the isotopic composition of its constituents (the ratio of 35Cl to 37Cl).', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The streams of magnetically sorted ions pass from the analyzer to the detector, which records the relative abundance of each ion type. This information is used to determine the chemical element composition of the original sample (i.e. that both sodium and chlorine are present in the sample) and the isotopic composition of its constituents (the ratio of 35Cl to 37Cl).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Sample inlet', 'The sample inlet provides a stream of neutral molecules, so that the ion source can ionize them. There are several classes. The classical design produces the stream of molecules in the form of a low-pressure gas. It is low-pressure, so that molecules within the stream do not frequently collide with each other. Ions must travel without frequent collisions, because the instrument separates ions by their motion in electric and magnetic fields. Collisions disturb that motion. Despite being low-pressure, the sample stream is still at a much higher pressure than the rest of the system, which is held in a greater vacuum. Consequently, the sample stream can only enter the ion source chamber via a small pinhole, called a molecular leak. If the sample itself is already a gas, then the sample inlet can simply be a gas inlet with pressure valve. If the sample is a volatile liquid or solid, then it can simply be placed in a chamber, vacuum-pumped to a low pressure. If the sample is not sufficiently volatile, the sample inlet can be fitted within an oven. Be careful not to decompose the sample.', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The sample inlet provides a stream of neutral molecules, so that the ion source can ionize them. There are several classes. The classical design produces the stream of molecules in the form of a low-pressure gas. It is low-pressure, so that molecules within the stream do not frequently collide with each other. Ions must travel without frequent collisions, because the instrument separates ions by their motion in electric and magnetic fields. Collisions disturb that motion. Despite being low-pressure, the sample stream is still at a much higher pressure than the rest of the system, which is held in a greater vacuum. Consequently, the sample stream can only enter the ion source chamber via a small pinhole, called a molecular leak. If the sample itself is already a gas, then the sample inlet can simply be a gas inlet with pressure valve. If the sample is a volatile liquid or solid, then it can simply be placed in a chamber, vacuum-pumped to a low pressure. If the sample is not sufficiently volatile, the sample inlet can be fitted within an oven. Be careful not to decompose the sample.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Sample inlet', 'If the sample is too nonvolatile to be turned into a low-pressure gas, then one can use a direct probe. The direct probe is a probe with a tip of thin wire loop, pin, or a capillary tube. The sample is placed in the tip. The probe is inserted through a vacuum lock into the ionization chamber, so that the tip is close to the ion source. The probe can be heated to increase vapor pressure further. Such a system is effective for samples with vapor pressures lower than The sample can be prepared by an earlier analyzer. For example, it can simply be the gaseous output of a gas chromatography machine as in GC-MS, or the liquid output of a high-performance liquid chromatography machine, as in HPLC-MS. The recently developed "atmospheric pressure ionization" techniques allow us to entirely dispense with the sample inlet.', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'If the sample is too nonvolatile to be turned into a low-pressure gas, then one can use a direct probe. The direct probe is a probe with a tip of thin wire loop, pin, or a capillary tube. The sample is placed in the tip. The probe is inserted through a vacuum lock into the ionization chamber, so that the tip is close to the ion source. The probe can be heated to increase vapor pressure further. Such a system is effective for samples with vapor pressures lower than The sample can be prepared by an earlier analyzer. For example, it can simply be the gaseous output of a gas chromatography machine as in GC-MS, or the liquid output of a high-performance liquid chromatography machine, as in HPLC-MS. The recently developed "atmospheric pressure ionization" techniques allow us to entirely dispense with the sample inlet.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Mass spectrometry: Ion source', 'The ion source is the part of the mass spectrometer that transforms the sample from the sample inlet into a stream of ions. There are many techniques with various dimensions for tradeoffs between different choices of ion sources, in terms of monetary cost, accuracy, precision, compatibility with other stages of spectroscopy, ease of use, etc. For example, electron ionization (EI) gives a high degree of fragmentation, yielding highly detailed mass spectra which when skilfully analysed can provide important information for structural elucidation/characterisation and facilitate identification of unknown compounds by comparison to mass spectral libraries obtained under identical operating conditions. However, EI is not suitable for coupling to HPLC, i.e. LC-MS, since at atmospheric pressure, the filaments used to generate electrons burn out rapidly. Thus EI is coupled predominantly with GC, i.e. GC-MS, where the entire system is under high vacuum. Two techniques often used with liquid and solid biological samples include electrospray ionization (invented by John Fenn) and matrix-assisted laser desorption/ionization (MALDI, initially developed as a similar technique Soft Laser Desorption) by K. Tanaka for which a Nobel Prize was awarded and as MALDI by M. Karas and F. Hillenkamp).', 'Wikipedia: Mass spectrometry', 'https://en.wikipedia.org/w/index.php?title=Mass_spectrometry&oldid=1378449939', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The ion source is the part of the mass spectrometer that transforms the sample from the sample inlet into a stream of ions. There are many techniques with various dimensions for tradeoffs between different choices of ion sources, in terms of monetary cost, accuracy, precision, compatibility with other stages of spectroscopy, ease of use, etc. For example, electron ionization (EI) gives a high degree of fragmentation, yielding highly detailed mass spectra which when skilfully analysed can provide important information for structural elucidation/characterisation and facilitate identification of unknown compounds by comparison to mass spectral libraries obtained under identical operating conditions. However, EI is not suitable for coupling to HPLC, i.e. LC-MS, since at atmospheric pressure, the filaments used to generate electrons burn out rapidly. Thus EI is coupled predominantly with GC, i.e. GC-MS, where the entire system is under high vacuum. Two techniques often used with liquid and solid biological samples include electrospray ionization (invented by John Fenn) and matrix-assisted laser desorption/ionization (MALDI, initially developed as a similar technique Soft Laser Desorption) by K. Tanaka for which a Nobel Prize was awarded and as MALDI by M. Karas and F. Hillenkamp).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis', 'Gel electrophoresis is a method for separation and analysis of biomacromolecules (DNA, RNA, proteins, etc.) and their fragments, based on their size and charge as they move through a gel under an electric field. It is used in clinical chemistry to separate proteins by charge or size and in biochemistry and molecular biology to separate a mixed population of DNA and RNA fragments by length, to estimate the size of DNA and RNA fragments, or to separate proteins by charge. Nucleic acid molecules are separated by applying an electric field to move the negatively charged molecules through a gel matrix of agarose, polyacrylamide, or other substances. Shorter molecules move faster and migrate farther than longer ones because shorter molecules flow more easily through the pores of the gel. This phenomenon is called sieving. Proteins are separated by the charge in agarose because the pores of the gel are too large to sieve proteins. Gel electrophoresis can also be used for the separation of nanoparticles.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Gel electrophoresis is a method for separation and analysis of biomacromolecules (DNA, RNA, proteins, etc.) and their fragments, based on their size and charge as they move through a gel under an electric field. It is used in clinical chemistry to separate proteins by charge or size and in biochemistry and molecular biology to separate a mixed population of DNA and RNA fragments by length, to estimate the size of DNA and RNA fragments, or to separate proteins by charge. Nucleic acid molecules are separated by applying an electric field to move the negatively charged molecules through a gel matrix of agarose, polyacrylamide, or other substances. Shorter molecules move faster and migrate farther than longer ones because shorter molecules flow more easily through the pores of the gel. This phenomenon is called sieving. Proteins are separated by the charge in agarose because the pores of the gel are too large to sieve proteins. Gel electrophoresis can also be used for the separation of nanoparticles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis', 'Gel electrophoresis uses a gel as an anticonvective medium or sieving medium during electrophoresis. Gels suppress the thermal convection caused by the application of the electric field and can also serve to maintain the finished separation so that a post-electrophoresis stain can be applied. DNA gel electrophoresis is usually performed for analytical purposes, often after amplification of DNA via polymerase chain reaction (PCR), but may be used as a preparative technique for other methods such as mass spectrometry, RFLP, PCR, cloning, DNA sequencing, or Southern blotting for further characterization.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Gel electrophoresis uses a gel as an anticonvective medium or sieving medium during electrophoresis. Gels suppress the thermal convection caused by the application of the electric field and can also serve to maintain the finished separation so that a post-electrophoresis stain can be applied. DNA gel electrophoresis is usually performed for analytical purposes, often after amplification of DNA via polymerase chain reaction (PCR), but may be used as a preparative technique for other methods such as mass spectrometry, RFLP, PCR, cloning, DNA sequencing, or Southern blotting for further characterization.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Physical basis', 'Electrophoresis is a process that enables the sorting of molecules based on charge, size, or shape. Using an electric field, molecules such as DNA can be made to move through a gel made of agarose or polyacrylamide. The electric field consists of a negative charge at one end which pushes the molecules through the gel and a positive charge at the other end that pulls the molecules through the gel. The molecules being sorted are dispensed into a well in the gel material. The gel is placed in an electrophoresis chamber, which is then connected to a power source. When the electric field is applied, the larger molecules move more slowly through the gel while the smaller molecules move faster. The different sized molecules form distinct bands on the gel.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Electrophoresis is a process that enables the sorting of molecules based on charge, size, or shape. Using an electric field, molecules such as DNA can be made to move through a gel made of agarose or polyacrylamide. The electric field consists of a negative charge at one end which pushes the molecules through the gel and a positive charge at the other end that pulls the molecules through the gel. The molecules being sorted are dispensed into a well in the gel material. The gel is placed in an electrophoresis chamber, which is then connected to a power source. When the electric field is applied, the larger molecules move more slowly through the gel while the smaller molecules move faster. The different sized molecules form distinct bands on the gel.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Physical basis', 'The term "gel" in this instance refers to the matrix used to contain, then separate the target molecules. In most cases, the gel is a crosslinked polymer whose composition and porosity are chosen based on the specific weight and composition of the target to be analyzed. When separating proteins or small nucleic acids (DNA, RNA, or oligonucleotides), the gel is usually composed of different concentrations of acrylamide and a cross-linker, producing different sized mesh networks of polyacrylamide. When separating larger nucleic acids (greater than a few hundred bases), the preferred matrix is purified agarose. In both cases, the gel forms a solid yet porous matrix. Acrylamide, in contrast to polyacrylamide, is a neurotoxin and must be handled using appropriate safety precautions to avoid poisoning. Agarose is composed of long unbranched chains of uncharged carbohydrates without cross-links, resulting in a gel with large pores allowing for the separation of macromolecules and macromolecular complexes.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The term "gel" in this instance refers to the matrix used to contain, then separate the target molecules. In most cases, the gel is a crosslinked polymer whose composition and porosity are chosen based on the specific weight and composition of the target to be analyzed. When separating proteins or small nucleic acids (DNA, RNA, or oligonucleotides), the gel is usually composed of different concentrations of acrylamide and a cross-linker, producing different sized mesh networks of polyacrylamide. When separating larger nucleic acids (greater than a few hundred bases), the preferred matrix is purified agarose. In both cases, the gel forms a solid yet porous matrix. Acrylamide, in contrast to polyacrylamide, is a neurotoxin and must be handled using appropriate safety precautions to avoid poisoning. Agarose is composed of long unbranched chains of uncharged carbohydrates without cross-links, resulting in a gel with large pores allowing for the separation of macromolecules and macromolecular complexes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Physical basis', 'Electrophoresis refers to the electromotive force (EMF) that is used to move the molecules through the gel matrix. By placing the molecules in wells in the gel and applying an electric field, the molecules will move through the matrix at different rates, determined largely by their mass when the charge-to-mass ratio (Z) of all species is uniform. However, when charges are not uniform, the electrical field generated by the electrophoresis procedure will cause the molecules to migrate differentially according to charge. Species that are net positively charged will migrate towards the cathode (which is negatively charged because this is an electrolytic rather than galvanic cell), whereas species that are net negatively charged will migrate towards the positively charged anode. Mass remains a factor in the speed with which these non-uniformly charged molecules migrate through the matrix toward their respective electrodes.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'Electrophoresis refers to the electromotive force (EMF) that is used to move the molecules through the gel matrix. By placing the molecules in wells in the gel and applying an electric field, the molecules will move through the matrix at different rates, determined largely by their mass when the charge-to-mass ratio (Z) of all species is uniform. However, when charges are not uniform, the electrical field generated by the electrophoresis procedure will cause the molecules to migrate differentially according to charge. Species that are net positively charged will migrate towards the cathode (which is negatively charged because this is an electrolytic rather than galvanic cell), whereas species that are net negatively charged will migrate towards the positively charged anode. Mass remains a factor in the speed with which these non-uniformly charged molecules migrate through the matrix toward their respective electrodes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Physical basis', 'If several samples have been loaded into adjacent wells in the gel, they will run parallel in individual lanes. Depending on the number of different molecules, each lane shows the separation of the components from the original mixture as one or more distinct bands, one band per component. Incomplete separation of the components can lead to overlapping bands, or indistinguishable smears representing multiple unresolved components. Bands in different lanes that end up at the same distance from the top contain molecules that passed through the gel at the same speed, which usually means they are approximately the same size. There are molecular weight size markers available that contain a mixture of molecules of known sizes. If such a marker was run on one lane in the gel parallel to the unknown samples, the bands observed can be compared to those of the unknown to determine their size. The distance a band travels is approximately inversely proportional to the logarithm of the size of the molecule. (Equivalently, the distance traveled is inversely proportional to the log of the samples''s molecular weight).', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'If several samples have been loaded into adjacent wells in the gel, they will run parallel in individual lanes. Depending on the number of different molecules, each lane shows the separation of the components from the original mixture as one or more distinct bands, one band per component. Incomplete separation of the components can lead to overlapping bands, or indistinguishable smears representing multiple unresolved components. Bands in different lanes that end up at the same distance from the top contain molecules that passed through the gel at the same speed, which usually means they are approximately the same size. There are molecular weight size markers available that contain a mixture of molecules of known sizes. If such a marker was run on one lane in the gel parallel to the unknown samples, the bands observed can be compared to those of the unknown to determine their size. The distance a band travels is approximately inversely proportional to the logarithm of the size of the molecule. (Equivalently, the distance traveled is inversely proportional to the log of the samples''s molecular weight).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Physical basis', 'There are limits to electrophoretic techniques. Since passing a current through a gel causes heating, gels may melt during electrophoresis. Electrophoresis is performed in buffer solutions to reduce pH changes due to the electric field, which is important because the charge of DNA and RNA depends on pH, but running for too long can exhaust the buffering capacity of the solution. There are also limitations in determining the molecular weight by SDS-PAGE, especially when trying to find the MW of an unknown protein. Certain biological variables are difficult or impossible to minimize and can affect electrophoretic migration. Such factors include protein structure, post-translational modifications, and amino acid composition. For example, tropomyosin is an acidic protein that migrates abnormally on SDS-PAGE gels. This is because the acidic residues are repelled by the negatively charged SDS, leading to an inaccurate mass-to-charge ratio and migration. Further, different preparations of genetic material may not migrate consistently with each other, for morphological or other reasons.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'There are limits to electrophoretic techniques. Since passing a current through a gel causes heating, gels may melt during electrophoresis. Electrophoresis is performed in buffer solutions to reduce pH changes due to the electric field, which is important because the charge of DNA and RNA depends on pH, but running for too long can exhaust the buffering capacity of the solution. There are also limitations in determining the molecular weight by SDS-PAGE, especially when trying to find the MW of an unknown protein. Certain biological variables are difficult or impossible to minimize and can affect electrophoretic migration. Such factors include protein structure, post-translational modifications, and amino acid composition. For example, tropomyosin is an acidic protein that migrates abnormally on SDS-PAGE gels. This is because the acidic residues are repelled by the negatively charged SDS, leading to an inaccurate mass-to-charge ratio and migration. Further, different preparations of genetic material may not migrate consistently with each other, for morphological or other reasons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'lab-techniques', 'Gel electrophoresis: Types of gel', 'The types of gel most typically used are agarose and polyacrylamide gels. Each type of gel is well-suited to different types and sizes of the analyte. Polyacrylamide gels are usually used for proteins and have very high resolving power for small fragments of DNA (5-500 bp). Agarose gels, on the other hand, have lower resolving power for DNA but a greater range of separation, and are therefore usually used for DNA fragments of 50–20,000 bp in size. (The resolution of over 6 Mb is possible with pulsed field gel electrophoresis (PFGE).) Polyacrylamide gels are run in a vertical configuration while agarose gels are typically run horizontally in a submarine mode. They also differ in their casting methodology, as agarose sets thermally, while polyacrylamide forms in a chemical polymerization reaction.', 'Wikipedia: Gel electrophoresis', 'https://en.wikipedia.org/w/index.php?title=Gel_electrophoresis&oldid=1373777361', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'lab-techniques' and body = 'The types of gel most typically used are agarose and polyacrylamide gels. Each type of gel is well-suited to different types and sizes of the analyte. Polyacrylamide gels are usually used for proteins and have very high resolving power for small fragments of DNA (5-500 bp). Agarose gels, on the other hand, have lower resolving power for DNA but a greater range of separation, and are therefore usually used for DNA fragments of 50–20,000 bp in size. (The resolution of over 6 Mb is possible with pulsed field gel electrophoresis (PFGE).) Polyacrylamide gels are run in a vertical configuration while agarose gels are typically run horizontally in a submarine mode. They also differ in their casting methodology, as agarose sets thermally, while polyacrylamide forms in a chemical polymerization reaction.');
